// #c4fe57 (עבר QA 26.10): карточка заказа /orders/<uuid> (просмотр), блок «פריטי ההזמנה» без горизонтальной прокрутки.
//   Раскладка — по ширине внутреннего блока (container query 600px): уже 600 — ряды «имя / מיקום במחסן / כמות × מחיר יחידה … סה"כ»,
//   от 600 — таблица «שם פריט · מיקום במחסן · כמות · מחיר יחידה · סה"כ» (Figma 36:278). Итоги «סכום ביניים» / «סה"כ לתשלום» —
//   подпись и сумма в одной строке внутри карточки. Значения: кол-во × цена = «סה"כ» строки, сумма строк = «סכום ביניים» = «סה"כ לתשלום».
//   Границы (вручную 26.10): с открытым боковым меню таблица с окна 1382 (1381 — ряды); без меню (окно < 1024) — с 706 (705 — ряды).
// Данные: заказ #650 (2 позиции, ₪105.00; поиск по номеру). Только просмотр — ничего не меняется → @prod-safe.
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/admin.json') });

const ORDER = '650';
type Layout = 'rows' | 'table';
type Box = { l: number; t: number; r: number; b: number; cy: number };

async function openOrder650(page: Page) {
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.goto('/orders');
  await expect(page.getByRole('heading', { level: 1, name: 'הזמנות' })).toBeVisible({ timeout: 30_000 });
  await page.getByRole('combobox', { name: 'סינון לפי חודש' }).selectOption({ label: 'כל החודשים' });
  await page.getByRole('textbox', { name: 'חיפוש לפי לקוח או מספר הזמנה' }).fill(ORDER);
  const row = page.getByRole('button', { name: new RegExp(`^#${ORDER} `) });
  await expect(row).toBeVisible({ timeout: 30_000 });
  await row.click();
  await expect(page).toHaveURL(/\/orders\/[0-9a-f-]{36}$/, { timeout: 30_000 });
  await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${ORDER}` })).toBeVisible({ timeout: 30_000 });
  await expect(page.getByText('סה"כ לתשלום', { exact: true }).first()).toBeVisible({ timeout: 20_000 });
}

/** Замер карточки «פריטי ההזמנה» (только чтение DOM). */
const measure = (page: Page) => page.evaluate(() => {
  const bx = (e: Element) => { const b = e.getBoundingClientRect(); return { l: b.left, t: b.top, r: b.right, b: b.bottom, cy: (b.top + b.bottom) / 2 }; };
  const vis = (e: Element) => e.getClientRects().length > 0 && getComputedStyle(e).display !== 'none' && getComputedStyle(e).visibility !== 'hidden';
  const clip = (e: Element) => e.scrollWidth > e.clientWidth + 1;
  const money = (s: string) => Math.round(Number(s.replace(/[₪,\s]/g, '')) * 100);
  const h = [...document.querySelectorAll('h1,h2,h3,h4')].find((e) => e.textContent!.trim() === 'פריטי ההזמנה')!;
  let card: HTMLElement = h.parentElement!;
  while (!card.querySelector('[class*="@container"]')) card = card.parentElement!; // карточка = предок заголовка с блоком container query
  const cont = card.querySelector('[class*="@container"]')!;
  const scrollers = [card, ...card.querySelectorAll('*')]
    .filter((e) => vis(e) && clip(e) && ['auto', 'scroll'].includes(getComputedStyle(e).overflowX))
    .map((e) => `${e.tagName} sw${e.scrollWidth}/cw${e.clientWidth}`);
  const leaf = (t: string) => [...card.querySelectorAll('*')].find((e) => e.children.length === 0 && e.textContent!.trim() === t);
  const header = ['שם פריט', 'מיקום במחסן', 'כמות', 'מחיר יחידה', 'סה"כ'].map((t) => { const e = leaf(t); return e && vis(e) ? { t, box: bx(e) } : null; });
  const rows = [...cont.querySelectorAll('*')]
    .filter((e) => e.querySelectorAll(':scope > [dir="ltr"]').length === 2 && e.querySelector('bdi[dir="ltr"]'))
    .map((row) => {
      const [priceEl, totEl] = [...row.querySelectorAll(':scope > [dir="ltr"]')];
      const qtyEl = row.querySelector('bdi[dir="ltr"]')!;
      const nameEl = row.children[0];
      const times = [...row.children].find((c) => c.textContent!.trim() === '×');
      return {
        name: nameEl.textContent!.trim(), nameBox: bx(nameEl),
        qty: Number(qtyEl.textContent!.trim()), qtyBox: bx(qtyEl), qtyClip: clip(qtyEl),
        price: priceEl.textContent!.trim(), priceC: money(priceEl.textContent!), priceBox: bx(priceEl), priceClip: clip(priceEl),
        tot: totEl.textContent!.trim(), totC: money(totEl.textContent!), totBox: bx(totEl), totClip: clip(totEl),
        timesVisible: !!times && vis(times), timesBox: times && vis(times) ? bx(times) : null,
      };
    });
  const totals = ['סכום ביניים', 'סה"כ לתשלום'].map((t) => {
    const lab = leaf(t)!;
    const amt = lab.parentElement!.querySelector('[dir="ltr"]')!;
    return { t, lab: bx(lab), amt: bx(amt), text: amt.textContent!.trim(), c: money(amt.textContent!), clip: clip(amt) };
  });
  return {
    vw: innerWidth, docSW: document.documentElement.scrollWidth, cardSW: card.scrollWidth, cardCW: card.clientWidth,
    card: bx(card), cw: cont.getBoundingClientRect().width, scrollers, header, rows, totals, scrollX,
  };
});

const inside = (a: Box, c: { l: number; r: number }) => a.l >= c.l - 0.5 && a.r <= c.r + 0.5;

/** Все проверки на одной ширине. expected — ожидаемая раскладка (по правилу container query 600px). */
async function checkWidth(page: Page, W: number, H: number, expected: Layout, menuOpen = false) {
  await page.setViewportSize({ width: W, height: H });
  await expect.poll(() => page.evaluate(() => innerWidth)).toBe(W);
  if (menuOpen) await expect(page.getByRole('button', { name: 'כיווץ', exact: true }), `${W}: боковое меню открыто`).toBeVisible();
  await expect(page.getByText('סה"כ לתשלום', { exact: true }).first()).toBeVisible();
  const m = await measure(page);
  const tag = `${W}×${H}`;
  const screen = { l: 0, r: m.vw };

  // раскладка по ширине внутреннего блока (600px)
  expect(m.cw < 600 ? 'rows' : 'table', `${tag}: внутренний блок ${Math.round(m.cw)}px → ${expected}`).toBe(expected);

  // нет горизонтальной прокрутки
  expect(m.docSW, `${tag}: страница без прокрутки вбок`).toBeLessThanOrEqual(m.vw + 1);
  expect(m.scrollX, `${tag}: окно не прокручено вбок`).toBe(0);
  expect(m.cardSW, `${tag}: карточка «פריטי ההזמנה» без прокрутки вбок`).toBeLessThanOrEqual(m.cardCW + 1);
  expect(m.scrollers, `${tag}: внутри карточки нет прокручиваемых вбок блоков`).toEqual([]);
  expect(inside(m.card, screen), `${tag}: карточка в экране`).toBe(true);

  // строки: имя, кол-во, цена, «סה"כ» — целиком в карточке и экране; кол-во × цена = סה"כ
  expect(m.rows.length, `${tag}: строки заказа #${ORDER}`).toBe(2);
  let sum = 0;
  for (const r of m.rows) {
    const rt = `${tag} «${r.name}»`;
    expect(r.name.length, `${rt}: имя`).toBeGreaterThan(0);
    for (const [what, b] of [['имя', r.nameBox], ['кол-во', r.qtyBox], ['цена', r.priceBox], ['סה"כ', r.totBox]] as const) {
      expect(inside(b, m.card), `${rt}: ${what} внутри карточки`).toBe(true);
      expect(inside(b, screen), `${rt}: ${what} внутри экрана`).toBe(true);
    }
    expect([r.qtyClip, r.priceClip, r.totClip], `${rt}: кол-во/цена/סה"כ не обрезаны`).toEqual([false, false, false]);
    expect(r.price, `${rt}: цена`).toMatch(/^₪[\d,]+\.\d\d$/);
    expect(r.tot, `${rt}: סה"כ`).toMatch(/^₪[\d,]+\.\d\d$/);
    expect(r.qty * r.priceC, `${rt}: ${r.qty} × ${r.price} = ${r.tot}`).toBe(r.totC);
    sum += r.totC;
    if (expected === 'rows') {
      expect(r.timesVisible, `${rt}: ряд «כמות × מחיר יחידה»`).toBe(true);
      for (const [what, b] of [['×', r.timesBox!], ['цена', r.priceBox], ['סה"כ', r.totBox]] as const) {
        expect(Math.abs(b.cy - r.qtyBox.cy), `${rt}: ${what} в одном ряду с кол-вом`).toBeLessThanOrEqual(3);
      }
      expect(r.qtyBox.t, `${rt}: ряд цены ниже имени`).toBeGreaterThanOrEqual(r.nameBox.b - 0.5);
    } else {
      expect(r.timesVisible, `${rt}: в таблице «×» скрыт`).toBe(false);
      for (const [what, b] of [['кол-во', r.qtyBox], ['цена', r.priceBox], ['סה"כ', r.totBox]] as const) {
        expect(Math.abs(b.cy - r.nameBox.cy), `${rt}: ${what} в одной строке таблицы с именем`).toBeLessThanOrEqual(3);
      }
    }
  }

  // заголовки таблицы
  if (expected === 'rows') {
    expect(m.header.filter(Boolean).map((x) => x!.t), `${tag}: узкая раскладка — без заголовков колонок`).toEqual([]);
  } else {
    expect(m.header.map((x) => x?.t), `${tag}: заголовки таблицы`).toEqual(['שם פריט', 'מיקום במחסן', 'כמות', 'מחיר יחידה', 'סה"כ']);
    for (let i = 1; i < m.header.length; i++) {
      expect(m.header[i]!.box.r, `${tag}: RTL — «${m.header[i]!.t}» левее «${m.header[i - 1]!.t}»`).toBeLessThanOrEqual(m.header[i - 1]!.box.l + 0.5);
    }
  }

  // итоги: подпись и сумма в одной строке, в карточке; сумма строк = סכום ביניים = סה"כ לתשלום (#650: ₪105.00)
  for (const x of m.totals) {
    expect(inside(x.lab, m.card) && inside(x.amt, m.card), `${tag}: «${x.t}» и сумма внутри карточки`).toBe(true);
    expect(inside(x.lab, screen) && inside(x.amt, screen), `${tag}: «${x.t}» и сумма внутри экрана`).toBe(true);
    expect(Math.abs(x.lab.cy - x.amt.cy), `${tag}: «${x.t}» — подпись рядом с суммой (одна строка)`).toBeLessThanOrEqual(3);
    expect(x.amt.r, `${tag}: «${x.t}» — RTL, сумма слева от подписи`).toBeLessThanOrEqual(x.lab.l + 0.5);
    expect(x.clip, `${tag}: сумма «${x.t}» не обрезана`).toBe(false);
  }
  expect(m.totals[0].c, `${tag}: «סכום ביניים» = сумма строк`).toBe(sum);
  expect(m.totals[1].c, `${tag}: «סה"כ לתשלום» = «סכום ביניים»`).toBe(m.totals[0].c);
  expect(m.totals[1].text, `${tag}: «סה"כ לתשלום» заказа #${ORDER}`).toBe('₪105.00');
}

test.describe('orders — כרטיס הזמנה: «פריטי ההזמנה» בלי גלילה לרוחב, שורות/טבלה לפי container query 600 (#c4fe57)', () => {
  test('טלפון 320/360/390/414 ולרוחב 667×375: שורות «כמות × מחיר» + «סה"כ», סיכומים עם הכותרת, ערכים נכונים #c4fe57 @iphone @orders @prod-safe', async ({ page }) => {
    test.setTimeout(120_000);
    await openOrder650(page);
    for (const [w, h] of [[320, 568], [360, 740], [390, 844], [414, 896], [667, 375]] as const) await checkWidth(page, w, h, 'rows');
  });

  test('1024/1100/1280 עם תפריט צד — שורות; 1381/1382 גבול; 1440 טבלה (Figma 36:278) #c4fe57 @desktop @orders @prod-safe', async ({ page }) => {
    test.setTimeout(120_000);
    await openOrder650(page);
    for (const [w, h] of [[1024, 768], [1100, 800], [1280, 800], [1381, 900]] as const) await checkWidth(page, w, h, 'rows', true);
    for (const [w, h] of [[1382, 900], [1440, 900]] as const) await checkWidth(page, w, h, 'table', true);
  });

  test('בלי תפריט צד: 705 שורות, 706 / 768 טבלה — בלי גלילה לרוחב #c4fe57 @desktop @orders @prod-safe', async ({ page }) => {
    test.setTimeout(120_000);
    await openOrder650(page);
    await checkWidth(page, 705, 900, 'rows');
    for (const [w, h] of [[706, 900], [768, 1024]] as const) await checkWidth(page, w, h, 'table');
  });
});
